// Saldo apenas das contas BANK do usuário que perguntou (antes somava Matheus + Ariane juntos)
const nome = $('Edit Fields').first().json.nome_usuario;
const mapa = {};
for (const it of $('Lista de Contas').all()) { mapa[it.json.accountId] = it.json.dono; }
let saldo = 0;
for (const item of $input.all()) {
  const a = item.json;
  if (a.type === 'BANK' && a.balance && mapa[a.id] === nome) saldo += a.balance;
}
return [{ json: { saldo_atual: saldo.toFixed(2) } }];

